import sys

def main():
    show_lines = False
    show_words = False
    show_chars = False
    filepath = None

    args = list(sys.argv[1:])
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-') and not arg.startswith('--'):
            for ch in arg[1:]:
                if ch == 'l':
                    show_lines = True
                elif ch == 'w':
                    show_words = True
                elif ch == 'c':
                    show_chars = True
        else:
            filepath = arg
        i += 1

    if filepath is None or filepath == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filepath, 'rb') as f:
            data = f.read()

    lines = data.count(b'\n')
    # A final line with no trailing newline still counts as a line
    if len(data) > 0 and not data.endswith(b'\n'):
        lines += 1
    words = len(data.split())
    chars = len(data)

    results = []
    if show_lines or show_words or show_chars:
        if show_lines:
            results.append(str(lines))
        if show_words:
            results.append(str(words))
        if show_chars:
            results.append(str(chars))
    else:
        results.append(str(lines))
        results.append(str(words))
        results.append(str(chars))

    print(' '.join(results))

if __name__ == '__main__':
    main()
